-- CAU HINH TRUNG TAM (docs/cau-hinh.md) - SINH TU tools/cauhinh/danh_muc.json boi
-- tools/cauhinh/sinh_cau_hinh.py, KHONG SUA TAY. Idempotent: chay lai bao nhieu lan cung duoc.
-- KHONG ghi gia tri vao cau_hinh: thieu dong = may chu dung server.ini roi mac dinh (CSDL > ini > mac dinh).
-- May chu game cung tu tao cac bang nay luc khoi dong (com.htbb.cauhinh.CauHinhTrungTam).

CREATE TABLE IF NOT EXISTS `cau_hinh` (
  `khoa` varchar(64) NOT NULL,
  `gia_tri` varchar(255) NOT NULL DEFAULT '',
  `sua_boi` varchar(50) DEFAULT NULL,
  `sua_luc` datetime DEFAULT NULL,
  PRIMARY KEY (`khoa`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE IF NOT EXISTS `cau_hinh_phien_ban` (`id` TINYINT NOT NULL, `phien_ban` BIGINT NOT NULL DEFAULT 0, `sua_luc` DATETIME NULL, `sua_boi` VARCHAR(50) NULL, PRIMARY KEY (`id`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE IF NOT EXISTS `cau_hinh_lich_su` (`id` BIGINT NOT NULL AUTO_INCREMENT, `khoa` VARCHAR(64) NOT NULL, `bang` VARCHAR(16) NOT NULL DEFAULT 'cau_hinh', `gia_tri_cu` VARCHAR(255) NULL, `gia_tri_moi` VARCHAR(255) NULL, `nguoi_sua` VARCHAR(50) NULL, `nguon` VARCHAR(20) NOT NULL DEFAULT '', `ly_do` VARCHAR(255) NOT NULL DEFAULT '', `phien_ban` BIGINT NOT NULL DEFAULT 0, `luc` DATETIME NOT NULL, PRIMARY KEY (`id`), KEY `idx_chls_khoa` (`khoa`), KEY `idx_chls_luc` (`luc`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE IF NOT EXISTS `cau_hinh_ap_dung` (`may_chu` VARCHAR(40) NOT NULL, `phien_ban` BIGINT NOT NULL DEFAULT 0, `ap_dung_luc` DATETIME NULL, `khoi_dong_luc` DATETIME NULL, `nhip_luc` DATETIME NULL, `so_khoa` INT NOT NULL DEFAULT 0, `so_loi` INT NOT NULL DEFAULT 0, `loi` TEXT NULL, `cho_khoi_dong_lai` TEXT NULL, `thay_doi_cuoi` TEXT NULL, PRIMARY KEY (`may_chu`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE IF NOT EXISTS `cau_hinh_hieu_luc` (`may_chu` VARCHAR(40) NOT NULL, `khoa` VARCHAR(64) NOT NULL, `gia_tri` VARCHAR(255) NULL, `nguon` VARCHAR(12) NOT NULL DEFAULT '', `cho_khoi_dong_lai` VARCHAR(255) NULL, `loi` VARCHAR(255) NULL, `cap_nhat_luc` DATETIME NULL, PRIMARY KEY (`may_chu`, `khoa`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE IF NOT EXISTS `cau_hinh_khoi_dong_lai` (`id` TINYINT NOT NULL, `trang_thai` VARCHAR(12) NOT NULL DEFAULT '', `giay` INT NOT NULL DEFAULT 60, `ly_do` VARCHAR(200) NOT NULL DEFAULT '', `yeu_cau_boi` VARCHAR(50) NULL, `yeu_cau_luc` DATETIME NULL, `bat_dau_luc` DATETIME NULL, `thoat_luc` DATETIME NULL, `xong_luc` DATETIME NULL, `may_chu` VARCHAR(40) NULL, PRIMARY KEY (`id`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;


-- Danh muc khoa + nhom (tra cuu / cong cu ngoai; may chu va web dung ban sinh trong ma nguon). DROP roi tao lai:
-- day la du lieu sinh, khong ai ghi tay; CSDL cu chua co cot lop / an / thu_tu va bang cau_hinh_nhom.
-- lop: chinh = chinh tren web; co_dinh = gia tri san xuat co dinh; luon_bat = luon 1. an = 1: khong hien tren trang,
-- may that bo qua dong cau_hinh cua khoa do (chi server.ini de khan cap) - xem docs/cau-hinh.md.
DROP TABLE IF EXISTS `cau_hinh_danh_muc`;
CREATE TABLE IF NOT EXISTS `cau_hinh_danh_muc` (`khoa` VARCHAR(64) NOT NULL, `nhom` VARCHAR(20) NOT NULL, `ten` VARCHAR(160) NOT NULL DEFAULT '', `mo_ta` TEXT NOT NULL, `kieu` VARCHAR(12) NOT NULL, `mac_dinh` VARCHAR(255) NOT NULL DEFAULT '', `gioi_han` TEXT NOT NULL, `ap_dung` VARCHAR(16) NOT NULL, `nhay` TINYINT NOT NULL DEFAULT 0, `khoa_prod` TINYINT NOT NULL DEFAULT 0, `chi_doc` TINYINT NOT NULL DEFAULT 0, `bang` VARCHAR(16) NOT NULL DEFAULT 'cau_hinh', `dung_o` VARCHAR(10) NOT NULL DEFAULT 'server', `nguon` VARCHAR(255) NOT NULL DEFAULT '', `thu_tu` INT NOT NULL DEFAULT 0, `lop` VARCHAR(10) NOT NULL DEFAULT 'chinh', `an` TINYINT NOT NULL DEFAULT 0, PRIMARY KEY (`khoa`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
DROP TABLE IF EXISTS `cau_hinh_nhom`;
CREATE TABLE IF NOT EXISTS `cau_hinh_nhom` (`ma` VARCHAR(20) NOT NULL, `ten` VARCHAR(160) NOT NULL DEFAULT '', `mo_ta` TEXT NOT NULL, `thu_tu` INT NOT NULL DEFAULT 0, `an` TINYINT NOT NULL DEFAULT 0, PRIMARY KEY (`ma`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

